// Generated by `just generate` from `src/plugins/claudetto/slices/asks/domain/checkcmd.ts`. Edit the source and run `just generate`.
// Whether a script or a recipe runs a check, from what it runs, as pure functions.
// A script is a check when one of its commands runs a known check program, or runs another script that is a check.
// The name of the script counts only when it is a documented entry name (`CHECK_ENTRY_NAMES`).
// The check reads the commands and no word of a language.

import {
  CHECK_ENTRY_NAMES,
  CHECK_PROGRAMS,
  CHECK_SUBCOMMANDS,
  SCRIPT_RUNNERS,
} from "../limits.ts";

/** What the check knows of one script or recipe: the text that it runs, and the names that it needs first. */
export interface Runnable {
  readonly text: string;
  readonly needs: readonly string[];
}

/** The commands in `text`, each as its words. A shell operator or a new line ends a command. A leading assignment of a variable is not a word. */
export const commandsOf = (text: string): string[][] =>
  text
    .split(/&&|\|\||[;|\n]/)
    .map((part) =>
      part
        .trim()
        .split(/\s+/)
        .filter(
          (word, i, all) =>
            word !== "" && !(i < all.length && /^\w+=/.test(word)),
        )
        .map((word, i) => (i === 0 ? word.replace(/^[@-]+/, "") : word)),
    )
    .filter((words) => words.length > 0);

const base = (word: string): string => word.split("/").at(-1) ?? word;

/** True when the command `words` runs a check program, a checking subcommand, `tsc` with `--noEmit`, or `bun` with `--check` (`bun test --check`, `bun run --check`, `bun build --check`). */
export const runsCheck = (words: readonly string[]): boolean => {
  const head = words.slice(0, 4).map(base);
  if (head.some((w) => CHECK_PROGRAMS.has(w))) return true;
  if (head.includes("tsc") && words.includes("--noEmit")) return true;
  if (head[0] === "bun" && words.includes("--check")) return true;
  const [program = "", ...rest] = head;
  const sub = rest.find((w) => !w.startsWith("-"));
  return sub !== undefined && (CHECK_SUBCOMMANDS[program] ?? []).includes(sub);
};

/** The names of the scripts or recipes that the command `words` runs, such as `lint` in `npm run lint` and `just lint`. */
export const referencedNames = (words: readonly string[]): string[] => {
  const [program = "", ...rest] = words;
  const shape = SCRIPT_RUNNERS[base(program)];
  const args = rest.filter((w) => !w.startsWith("-"));
  if (shape === undefined) return [];
  if (shape === "direct") return args;
  if (args[0] === "run" || args[0] === "run-script") return args.slice(1);
  return shape === "optional-run" ? args.slice(0, 1) : [];
};

/** True when `name` is a check: a documented entry name, or a script that runs a check or needs one. `find` gives the script of a name. */
export const isCheck = (
  name: string,
  find: (name: string) => Runnable | undefined,
  seen: Set<string> = new Set(),
): boolean => {
  if (seen.has(name)) return false;
  seen.add(name);
  if (CHECK_ENTRY_NAMES.has(name)) return true;
  const found = find(name);
  if (found === undefined) return false;
  return (
    found.needs.some((n) => isCheck(n, find, seen)) ||
    commandsOf(found.text).some(
      (words) =>
        runsCheck(words) ||
        referencedNames(words).some((n) => isCheck(n, find, seen)),
    )
  );
};
